// server adds a prefix of https://[env] and a suffix of .svg to path of file.
// this function removes the prefix and suffix since we are using base64 encoded svg
export const cleanBase64Svg = (iconUrl = '') => {
  const isBase64EncodedSvg = iconUrl?.startsWith('https://') && iconUrl?.includes('svg+xml;base64');
  if (isBase64EncodedSvg) {
    const [_, base64] = iconUrl.split('svg+xml;base64,');
    const cleanBase64 = base64.replace('.svg', '');
    return `data:image/svg+xml;base64,${cleanBase64}`;
  } else {
    return iconUrl;
  }
};
